func lengthOfLastWord(s string) int {
	end := len(s) - 1
	for end >= 0 && s[end] == ' ' {
		end--
	}
	start := end
	for start >= 0 && s[start] != ' ' {
		start--
	}
	return end - start
}

class Solution {
  public int lengthOfLastWord(String s) {
    int end = s.length() - 1;
    while (end >= 0 && s.charAt(end) == ' ') {
      end--;
    }
    int start = end;
    while (start >= 0 && s.charAt(start) != ' ') {
      start--;
    }
    return end - start;
  }
}

class Solution:
    def lengthOfLastWord(self, s: str) -> int:
        end = len(s) - 1
        while end >= 0 and s[end] == " ":
            end -= 1
        start = end
        while start >= 0 and s[start] != " ":
            start -= 1
        return end - start

impl Solution {
  pub fn length_of_last_word(s: String) -> i32 {
    let bytes = s.as_bytes();
    let mut end = bytes.len() as i32 - 1;
    while end >= 0 && bytes[end as usize] == b' ' {
      end -= 1;
    }
    let mut start = end;
    while start >= 0 && bytes[start as usize] != b' ' {
      start -= 1;
    }
    end - start
  }
}

const lengthOfLastWord = (s: string): number => {
  let end = s.length - 1;
  while (end >= 0 && s[end] === ' ') end--;
  let start = end;
  while (start >= 0 && s[start] !== ' ') start--;
  return end - start;
};

class Solution {
public:
  int lengthOfLastWord(string s) {
    size_t foundNot = s.find_last_not_of(" ");
    if (foundNot == string::npos) {
      return 0;
    } else {
      if (foundNot != (s.size() - 1)) {
        s.erase(s.begin() + foundNot + 1, s.end());
      }
      return s.size() - s.find_last_of(" ") - 1;
    }
  }
};
